// HashiCorp Vault - envelope encryption demo
var crypto = require("crypto");
function seal(secret, key) {
  var iv = crypto.randomBytes(12);
  var c = crypto.createCipheriv("aes-256-gcm", crypto.createHash("sha256").update(key).digest(), iv);
  var ct = Buffer.concat([c.update(secret, "utf8"), c.final()]);
  return { iv: iv.toString("hex"), ct: ct.toString("hex"), tag: c.getAuthTag().toString("hex") };
}
function open(env, key) {
  var d = crypto.createDecipheriv("aes-256-gcm", crypto.createHash("sha256").update(key).digest(), Buffer.from(env.iv, "hex"));
  d.setAuthTag(Buffer.from(env.tag, "hex"));
  return Buffer.concat([d.update(Buffer.from(env.ct, "hex")), d.final()]).toString("utf8");
}
var env = seal("db-password-42", "vault-key");
console.log("Vault model: HashiCorp Vault | Crypto: AES-256-GCM / Shamir seal");
console.log("Sealed bytes: " + env.ct.length);
console.log("Unseal round-trip: " + (open(env, "vault-key") === "db-password-42" ? "PASS" : "FAIL"));

